// The scorecard. Everything here answers a question a client actually asks:
// is the machine running, is it about to run out of leads, and is anything stuck?
const leads = $('[cred] Sheets - read leads').all().map((i) => i.json);
const execs = (($input.first().json || {}).data) || [];

const CAP = Number($env.DAILY_SEND_CAP || 80);
const MIN_RUNWAY_DAYS = Number($env.MIN_RUNWAY_DAYS || 5);
const REPLY_SLA_HOURS = Number($env.REPLY_SLA_HOURS || 24);

let stages = {};
for (const lead of leads) {
  const s = String(lead.stage || 'unknown').trim() || 'unknown';
  stages[s] = (stages[s] || 0) + 1;
}

const sendable = leads.filter((l) =>
  l.email &&
  Number(l.confidence || 0) >= Number($env.MIN_CONFIDENCE || 70) &&
  ['new', 'researched', 'enriched'].indexOf(String(l.stage || '').trim()) !== -1
).length;

const runwayDays = CAP > 0 ? Math.floor(sendable / CAP) : 0;
const enrichBacklog = leads.filter((l) => !l.email && String(l.stage || '') !== 'suppressed').length;

// Replies waiting on a human for longer than the SLA.
const now = Date.now();
const staleReplies = leads.filter((l) => {
  if (String(l.stage || '') !== 'replied') return false;
  const t = Date.parse(l.updated_at || l.received_at || '') || 0;
  return t > 0 && (now - t) / 3600000 > REPLY_SLA_HOURS;
}).length;

// Which pipeline workflows ran in the last 24h, and did they succeed.
let watched = {};
try { watched = JSON.parse($env.PIPELINE_WORKFLOW_IDS || '{}'); } catch (e) {
  throw new Error('PIPELINE_WORKFLOW_IDS is not valid JSON: ' + String(e.message));
}

const dayAgo = now - 24 * 3600000;
const stalls = [];
const failures = [];

for (const label of Object.keys(watched)) {
  const id = String(watched[label]);
  const recent = execs.filter((e) => String(e.workflowId) === id && (Date.parse(e.startedAt || '') || 0) > dayAgo);
  if (recent.length === 0) {
    stalls.push(label);
    continue;
  }
  const errored = recent.filter((e) => String(e.status || '') === 'error').length;
  if (errored > 0) failures.push(label + ' (' + errored + '/' + recent.length + ' failed)');
}

const healthy = stalls.length === 0 && failures.length === 0 && runwayDays >= MIN_RUNWAY_DAYS && staleReplies === 0;

return [{ json: {
  healthy: healthy,
  stages: stages,
  sendable: sendable,
  runway_days: runwayDays,
  min_runway_days: MIN_RUNWAY_DAYS,
  enrich_backlog: enrichBacklog,
  stale_replies: staleReplies,
  reply_sla_hours: REPLY_SLA_HOURS,
  stalls: stalls,
  failures: failures,
  executions_seen: execs.length,
  date: new Date().toISOString().slice(0, 10)
}}];

// Format for a phone screen. Lead with the thing that needs a decision, not with a
// wall of green ticks - a report nobody reads is the same as no report.
const s = $input.first().json;
const lines = [];

lines.push((s.healthy ? ':white_check_mark:' : ':rotating_light:') + ' *Outbound system - ' + s.date + '*');

if (s.stalls.length) lines.push(':rotating_light: *Did not run in 24h:* ' + s.stalls.join(', '));
if (s.failures.length) lines.push(':x: *Errors:* ' + s.failures.join(', '));
if (s.runway_days < s.min_runway_days) {
  lines.push(':hourglass: *Runway ' + s.runway_days + ' days* (' + s.sendable + ' sendable leads). Below the ' + s.min_runway_days + '-day floor - build more list.');
}
if (s.stale_replies) {
  lines.push(':envelope: *' + s.stale_replies + ' replies waiting over ' + s.reply_sla_hours + 'h.* This is the expensive one.');
}

if (s.healthy) lines.push('Runway ' + s.runway_days + ' days, ' + s.sendable + ' sendable, no stalls, no replies overdue.');

const byStage = Object.keys(s.stages).sort().map((k) => k + ' ' + s.stages[k]).join('  |  ');
lines.push('_' + byStage + '_');
if (s.enrich_backlog) lines.push('_' + s.enrich_backlog + ' rows still need an email address._');

return [{ json: { text: lines.join('\n'), healthy: s.healthy } }];
